package net.hivel.islandsrpg.island;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.configuration.file.*; import org.bukkit.entity.Player; import java.io.File; import java.util.*;
public class IslandService { private final IslandsRPGPlugin plugin; private final Map<String,Island> islands=new LinkedHashMap<>(); private FileConfiguration config; public IslandService(IslandsRPGPlugin p){plugin=p;} public void reload(){config=ConfigUtil.load(plugin,"islands.yml"); islands.clear(); var sec=config.getConfigurationSection("islands"); if(sec==null)return; for(String id:sec.getKeys(false)){String path="islands."+id+"."; Location l=LocationUtil.parse(plugin,config.getString(path+"spawn","world,0,80,0")); Material icon=Material.matchMaterial(config.getString(path+"icon","GRASS_BLOCK")); islands.put(id,new Island(id,config.getString(path+"display-name",id),config.getInt(path+"required-level",1),icon==null?Material.GRASS_BLOCK:icon,l));}} public Collection<Island> all(){return islands.values();} public Island get(String id){return islands.get(id);} public boolean canUse(PlayerData d,Island i){return i!=null && (d.level>=i.requiredLevel()||d.unlockedIslands.contains(i.id()));} public void visit(Player p,String id){Island i=get(id); if(i==null)return; PlayerData d=plugin.data().get(p); if(!canUse(d,i)){p.sendMessage(ColorUtil.color(plugin.message("locked-island").replace("%level%",String.valueOf(i.requiredLevel()))));return;} if(i.spawn()!=null)p.teleport(i.spawn()); d.unlockedIslands.add(i.id()); plugin.quests().handleVisitIsland(p,id); plugin.data().save(d);} public boolean setSpawn(String id, Location loc){if(!islands.containsKey(id))return false; config.set("islands."+id+".spawn",LocationUtil.serialize(loc)); try{config.save(new File(plugin.getDataFolder(),"islands.yml"));}catch(Exception e){return false;} reload(); return true;} }
